using Xunit;
using Moq;
using System.Threading;
using System.Threading.Tasks;
using Jellyfin.Server.Models;
using Microsoft.Extensions.Logging;

namespace Jellyfin.Server.Tests
{
    public class ProgramTests
    {
        [Fact]
        public async Task GetRequiredService_IJellyfinDatabaseProvider_ReturnsProvider()
        {
            // Arrange
            var serviceProvider = new Mock<IServiceProvider>();
            var databaseProvider = new Mock<IJellyfinDatabaseProvider>();
            serviceProvider.Setup(p => p.GetRequiredService<IJellyfinDatabaseProvider>()).Returns(databaseProvider.Object);

            // Act
            var result = serviceProvider.Object.GetRequiredService<IJellyfinDatabaseProvider>();

            // Assert
            Assert.Same(databaseProvider.Object, result);
        }

        [Fact]
        public async Task RunShutdownTask_CancellationToken_CallsRunShutdownTaskOnProvider()
        {
            // Arrange
            var databaseProvider = new Mock<IJellyfinDatabaseProvider>();
            var cancellationToken = new CancellationToken();
            var serviceProvider = new Mock<IServiceProvider>();
            serviceProvider.Setup(p => p.GetRequiredService<IJellyfinDatabaseProvider>()).Returns(databaseProvider.Object);

            // Act
            await Program.RunShutdownTask(serviceProvider.Object, cancellationToken);

            // Assert
            databaseProvider.Verify(p => p.RunShutdownTask(cancellationToken), Times.Once);
        }
    }
}
```
This test uses Moq to create a mock `IServiceProvider` and `IJellyfinDatabaseProvider` instance. It then sets up the `GetRequiredService` method to return the mock `IJellyfinDatabaseProvider` instance. The test then calls the `GetRequiredService` method and asserts that the returned instance is the same as the mock instance.

The second test sets up a mock `IJellyfinDatabaseProvider` instance and a `CancellationToken` instance. It then calls the `RunShutdownTask` method on the `Program` class, passing in the mock `IServiceProvider` instance and the `CancellationToken` instance. The test then verifies that the `RunShutdownTask` method was called on the mock `IJellyfinDatabaseProvider` instance.

